import Taro from '@tarojs/taro';
// @ts-ignore
import { api, baseConfig } from './api';
// @ts-ignore
import rootConfig from './rootConfig';

export function request(connector: any, params: any, config: any = {}, appContext?: any) {
  const connectorId = connector.id;
  const def = api[connectorId];

  if (!def) {
    return Promise.reject(`未找到连接器定义: ${connectorId}`);
  }

  return new Promise((resolve, reject) => {
    try {
      const method = def.method;
      const path = def.path?.trim();
      let headers = def.headers || {};

      const url = path;
      const extraParams = {
        globalVars: appContext?.$vars?.current
      };

      // 设置全局请求头逻辑组件
      let mybricksGlobalHeaders = Taro.getStorageSync(
        "_MYBRICKS_GLOBAL_HEADERS_"
      );
      if (mybricksGlobalHeaders) {
        headers = {
          ...mybricksGlobalHeaders,
          ...headers,
        };
      }

      /** 1. 全局入参处理 */
      const globalParams = baseConfig.globalParamsFn(
        method.startsWith('GET')
          ? { params, url, method, headers }
          : { data: params, url, method, headers },
        extraParams
      );

      /** 2. 局部入参处理 (Connector Script) */
      const options = def.input(globalParams, extraParams);

      const requestConfig: Taro.request.Option = {
        url: options.url || url,
        method: (options.method || method) as any,
        header: options.headers || options.header || headers,
        data: options.data || options.params || params,
        timeout: options.timeout || config.timeout,
        dataType: options.dataType || config.dataType || 'json',
        responseType: options.responseType || config.responseType || 'text',
      };

      /**
       * 如果 url 不以 http 开头，添加默认域名
       */
      const defaultCallServiceHost = rootConfig?.status?.defaultCallServiceHost
      if (
        !/^(http|https):\/\/.*/.test(requestConfig.url) &&
        defaultCallServiceHost
      ) {
        requestConfig.url = `${defaultCallServiceHost}${requestConfig.url}`;
      }

      const onError = (error: any) => {
        const errorResult = baseConfig.globalErrorResultFn(
          { error, response: error?.response, config: options },
          { throwError: (msg: any) => reject(msg) }
        );
        if (errorResult !== undefined) {
          reject(errorResult);
        }
      };

      Taro.request({
        ...requestConfig,
        success: (res) => {
          /** 3. 全局响应值处理 */
          Promise.resolve()
            .then(() => {
              return baseConfig.globalResultFn(
                { response: res.data, config: options },
                { 
                  throwStatusCodeError: (msg: any) => reject(msg),
                  throwError: (msg: any) => reject(msg)
                }
              );
            })
            .then((globalResult) => {
              /** 4. 局部响应值处理 (Connector Script) */
              const result = def.output(
                globalResult,
                { ...options },
                { 
                  throwStatusCodeError: (msg: any) => reject(msg),
                  throwError: (msg: any) => reject(msg)
                }
              );

              // 处理 markList (多分支输出)
              const markList = def.markList || [];
              let outputId = 'then';

              if (markList.length > 0) {
                for (const mark of markList) {
                  const { id, predicate } = mark;
                  if (!predicate || !predicate.key || predicate.value === undefined) {
                    outputId = id === 'default' ? 'then' : id;
                    break;
                  }

                  let curResult = result;
                  const keys = predicate.key.split('.');
                  while (curResult && keys.length) {
                    curResult = curResult[keys.shift()];
                  }

                  if (!keys.length && (
                    predicate.operator === '=' 
                      ? curResult === predicate.value 
                      : curResult !== predicate.value
                  )) {
                    outputId = id === 'default' ? 'then' : id;
                    break;
                  }
                }
              }

              // 返回包含 OUTPUT_ID 的结果，供 _Connector.ts 使用
              resolve({
                __OUTPUT_ID__: outputId,
                __ORIGIN_RESPONSE__: result
              });
            })
            .catch(onError);
        },
        fail: (err) => {
          reject(err?.errMsg || "连接器执行失败");
        },
      });
    } catch (error: any) {
      console.error('连接器执行失败:', error);
      reject(error?.message || '连接器执行失败');
    }
  });
}

import React, { useCallback, useMemo, useState, useEffect } from "react";
import * as Taro from "@tarojs/taro";
import { View, Image } from "@tarojs/components";
import { DynamicIcon } from "@mybricks/taro-components";
import css from "./style.module.less";
import tabBarJson from "./mybricks/tabbar-config";
import { tabbarIns } from "@mybricks/taro-core";

tabbarIns.initWithLength(tabBarJson.length);

function CustomTabBar() {
  const [configList, setConfigList] = useState(tabbarIns.list);

  const switchTab = useCallback((url) => {
    Taro.switchTab({ url: `/${url}` });
  }, []);

  useEffect(() => {
    tabbarIns.eventEmitter.addEventListner("change", (list) => {
      setConfigList(list.map((t) => t));
    });
  }, []);

  const tabList = useMemo(() => {
    return tabBarJson.map((item, index) => {
      const config = configList?.[index] ?? {};
      return {
        ...item,
        ...config,
      };
    });
  }, [tabBarJson, configList]);

  // 故意的只渲染一次，只在加载的时候渲染，符合预期
  const currentRoute = useMemo(() => {
    let pages = Taro.getCurrentPages();
    return pages[pages.length - 1].route;
  }, []);

  const iconRender = (itemData, isSelected) => {
    let useImgIcon = isSelected
      ? itemData.selectedIconUseImg !== false
      : itemData.normalIconUseImg !== false;
    let icon = isSelected ? itemData.selectedIcon : itemData.normalIcon;

    let iconStyle = isSelected
      ? itemData.selectedFontIconStyle
      : itemData.normalFontIconStyle;

    let imgIcon = isSelected
      ? itemData.selectedIconPath
      : itemData.normalIconPath;

    let imgIconStyle = isSelected
      ? itemData.selectedIconStyle
      : itemData.normalIconStyle;

    let formatText = "";
    if (itemData.active) {
      switch (true) {
        case typeof parseFloat(itemData?.activeText) === "number":
          if (itemData?.activeText > 0 && itemData?.activeText < 100) {
            formatText = itemData?.activeText;
          } else if (itemData?.activeText > 100) {
            formatText = "99+";
          }
          break;
        case typeof itemData.activeText === "string": {
          formatText =
            itemData?.activeText.length > 3
              ? `${itemData?.activeText.slice(0, 2)}...`
              : itemData?.activeText;
          break;
        }
      }
    }
    return (
      <View className={css.iconSlot}>
        {useImgIcon ? (
          <Image
            style={{
              display: "block",
              width: "22px",
              height: "22px",
              ...imgIconStyle,
            }}
            src={imgIcon}
          />
        ) : (
          <DynamicIcon
            className={css.fontIcon}
            name={icon}
            size={iconStyle?.fontSize}
            color={iconStyle?.color}
          />
        )}
        {itemData.active && (
          <View
            className={`${css.badge} ${!formatText ? css.small : css.normal}`}
          >
            {formatText}
          </View>
        )}
      </View>
    );
  };

  const $tabBars = useMemo(() => {
    return tabList.map((raw, index) => {
      let pagePath = raw.pagePath;

      let isSelected = pagePath === currentRoute;

      let textStyle = isSelected ? raw.selectedTextStyle : raw.normalTextStyle;
      let backgroundStyle = isSelected
        ? raw.selectedBackgroundStyle
        : raw.normalBackgroundStyle;

      return (
        <View
          className={css.item}
          key={index}
          onClick={() => {
            switchTab(raw.pagePath);
          }}
          style={{ ...backgroundStyle }}
        >
          {iconRender(raw, isSelected)}

          {raw.text && (
            <View className={css.textSlot} style={{ ...textStyle }}>
              {raw.text}
            </View>
          )}
        </View>
      );
    });
  }, [tabList, currentRoute]);

  return (
    <View className={css.tabBar}>
      <View className={css.items}>{$tabBars}</View>
      <View className={css.safearea}></View>
    </View>
  );
}

export default CustomTabBar;
CustomTabBar.options = {
  addGlobalClass: true,
};

.tabBar {
  width: 375px;
  background: #ffffff;
  box-shadow: 0px 4px 10px 0px rgba(0, 0, 0, 0.1);
  z-index: 9999;

  .items {
    width: 375px;
    height: 54px;
    display: flex;
  }

  .safearea {
    width: 375px;
    height: constant(safe-area-inset-bottom);
    height: env(safe-area-inset-bottom);
  }

  .item {
    position: relative;
    flex: 1;
    height: 100%;
    padding-top: 6px;
    padding-bottom: 6px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    .iconSlot {
      position: relative;
      .fontIcon {
        display: block;
      }

      .badge {
        position: absolute;

        transform-origin: 100% 0%;
        transform: translate(50%, -40%);

        top: 0px;
        right: 0px;

        background-color: #ff4d4f;
      }
      .badge.normal {
        padding: 0px 3px;
        min-width: 14px;
        height: 14px;
        border-radius: 100px;
        font-size: 10px;

        display: flex;
        align-items: center;
        justify-content: center;
        color: #fff;
      }
      .badge.small {
        width: 9px;
        height: 9px;
        border-radius: 50%;
      }
    }

    .textSlot {
      margin-top: 6px;
      height: 14px;
    }
  }
}

